<script>
export default {
    name: 'BpmnReviewGuide',
    props: {
        activeTab: {
            type: String,
            default: null,
            validator: v => v === null || v === 'bpmn' || v === 'checklist',
        },
    },
    methods: {
        toggleCheck(event) {
            const item = event.currentTarget;
            item.classList.toggle('checked');
            this.updateProgress();
        },
        resetAll() {
            const items = this.$el.querySelectorAll('.checklist-item.checked');
            items.forEach(el => el.classList.remove('checked'));
            this.updateProgress();
        },
        updateProgress() {
            const total = 8;
            const n = this.$el.querySelectorAll('.checklist-item.checked').length;
            const pct = Math.round((n / total) * 100);
            const textEl = this.$el.querySelector('#progress-text');
            const barEl = this.$el.querySelector('#progress-bar');
            if (textEl) textEl.textContent = n + ' / ' + total + ' 완료';
            if (barEl) barEl.style.width = pct + '%';
        },
    },
};
</script>

